 const receipt={schemaVersion:1,kind:'pr356-qualification',head:H,tree:T,base:B,candidateInputsSHA256:plan.candidateInputsSHA256,inventorySHA256:plan.inventorySHA256,acceptanceSHA256:plan.acceptanceSHA256,requiredPhaseIds:plan.requiredPhaseIds,phaseInputs:copy(Object.fromEntries(Object.entries(phases).map(([id,p])=>[id,p.inputs]))),phases:rows,historicalEvidence:history,roleArtifacts:[role],sarif:['javascript-typescript','python'].map(language=>({schemaVersion:1,phaseId:'codeql-'+language,status:'analysis-complete',disposition:'pending',sourceHead:H,sourceTree:T,language,suite:'security-extended',sarifSHA256:digest,analysisSHA256:digest,queryPackSHA256:digest,queryCount:1,runCount:1,findings:[],resultSetSHA256:canonicalSHA256([]),analysisSuccessful:true,zeroFindings:true,policySHA256:plan.sarifPolicy.sha256,externalDotApprovalRequired:true,reviewAuthentication:'not-established',releaseAuthorized:false})),qualificationOnly:true,externalDotApprovalRequired:true,reviewAuthentication:'not-established',releaseAuthorized:false};
