 const fetcher=async(url,options)=>{const u=new URL(url);assert.equal(u.origin,'https://api.github.com');assert.equal(options.headers.Authorization,'Bearer synthetic-read-token');const path=u.pathname.replace('/repos/'+REPOSITORY+'/','');paths.push(path+(u.search||''));if(path.endsWith('/zip')){assert.equal(path,'actions/artifacts/5001/zip','Original image/DB/browser/CodeQL ZIP download is forbidden by metadata-only contract');return new Response(zip,{status:200});}let value;const a=/^actions\/artifacts\/([0-9]+)$/.exec(path),j=/^actions\/jobs\/([0-9]+)$/.exec(path),r=/^actions\/runs\/1001\/attempts\/([12])$/.exec(path),list=/^actions\/runs\/1001\/attempts\/([12])\/jobs$/.exec(path);if(a)value=artifacts.get(a[1]);else if(j)value=jobs.get(j[1]);else if(r)value=run(Number(r[1]));else if(list)value={jobs:[...jobs.values()].filter(j=>j.run_attempt===Number(list[1]))};else throw Error('Unexpected endpoint (no broad lookup/fallback/application): '+path);return {status:value?200:404,json:async()=>copy(value)};};
