async function withRoot(fn,{changeReceipt,changeProof}={}){const f=fixture();if(changeReceipt||changeProof)f.packageRoot(changeReceipt,changeProof);const dir=mkdtempSync(join(tmpdir(),'pr356-metadata-control-'));try{return await fn(f,join(dir,'official-q'));}finally{rmSync(dir,{recursive:true,force:true});}}
const authenticate=(f,directory)=>authenticateQualificationRoot({plan:f.plan,pin:f.pin,directory,token:'synthetic-read-token',fetcher:f.fetcher});

test('actual small official Q ZIP forms a nonforgeable root; reuse GETs metadata only and accepts original attempt 1 under Q attempt 2',async()=>withRoot(async(f,directory)=>{
 const root=await authenticate(f,directory),before=f.paths.length,result=await verifyQualificationMetadata({plan:f.plan,root,token:'synthetic-read-token',fetcher:f.fetcher});assert.equal(result.phaseMetadata.length,17);assert.equal(result.originalPhaseArchivesDownloaded,false);assert.equal(result.applicationChecksExecuted,false);assert.equal(result.qualificationClaim,false);assert.equal(result.releaseAuthorized,false);assert(result.phaseMetadata.every(p=>p.official.attempt==='1'));assert.equal(f.paths.filter(p=>p.endsWith('/zip')).length,1);assert.equal(f.paths.find(p=>p.endsWith('/zip')),'actions/artifacts/5001/zip');assert(f.paths.slice(before).every(p=>/^actions\/(?:jobs\/[0-9]+|artifacts\/[0-9]+|runs\/1001\/attempts\/[12])$/.test(p)),'Only fixed job/artifact/run metadata is allowed after Q root');assert.equal(root.validation.role,'qualification-result','The actual archive verifier must only consume Q, never image/TARCHECK roles');assert.throws(()=>root.receipt.phases.pop());await assert.rejects(verifyQualificationMetadata({plan:f.plan,root:copy(root),token:'synthetic-read-token',fetcher:async()=>{throw Error('Unbranded JSON must fail before network');}}),/authenticated official Q ZIP/);
}));

test('complete source recipes, phase/case tables, pending analysis and actual upstream identities fail closed before metadata reuse',async()=>{
 for(const mutate of [r=>r.phases.pop(),r=>r.phaseInputs['backend-image'].configuration.kind='drift',r=>r.phases[0].checks[0].status='skipped',r=>r.phases.find(p=>p.phaseId==='backend-scan').upstream[0].proofSHA256='0'.repeat(64),r=>r.roleArtifacts[0].proofSHA256='0'.repeat(64),r=>r.sarif[0].disposition='accepted',r=>r.historicalEvidence.cases[0].originalExecutionSigned=true])await withRoot(async(f,directory)=>{await assert.rejects(authenticate(f,directory));},{changeReceipt:mutate});
});

test('original fixed metadata failure, expiry, source/digest/job drift and denied reads cannot fall back or fetch original ZIPs',async()=>withRoot(async(f,directory)=>{
 const root=await authenticate(f,directory),job=copy(f.jobs.get('2001')),artifact=copy(f.artifacts.get('3001'));
 for(const change of [()=>f.jobs.get('2001').conclusion='failure',()=>f.jobs.get('2001').status='queued',()=>f.jobs.get('2001').id=9999,()=>f.jobs.get('2001').head_sha=B,()=>f.artifacts.get('3001').expired=true,()=>f.artifacts.get('3001').expires_at='2000-01-01T00:00:00Z',()=>f.artifacts.get('3001').digest='sha256:'+'0'.repeat(64)]){f.jobs.set('2001',copy(job));f.artifacts.set('3001',copy(artifact));change();await assert.rejects(verifyQualificationMetadata({plan:f.plan,root,token:'synthetic-read-token',fetcher:f.fetcher}));}
 f.jobs.set('2001',job);f.artifacts.set('3001',artifact);const denied=[];await assert.rejects(verifyQualificationMetadata({plan:f.plan,root,token:'synthetic-read-token',fetcher:async(url,options)=>{const p=new URL(url).pathname;denied.push(p);if(p.endsWith('/actions/jobs/2001'))return {status:403};return f.fetcher(url,options);}}),/no retry\/fallback/);assert.equal(denied.filter(p=>p.endsWith('/actions/jobs/2001')).length,1);assert.equal(f.paths.filter(p=>p.endsWith('/zip')).length,1,'Failed metadata reads never download any original phase ZIP');
}));

test('Q itself needs official successful job and complete bound standard proof; pending plans never obtain an authenticated root',async()=>{
 await withRoot(async(f,directory)=>{f.jobs.get('4001').conclusion='failure';await assert.rejects(authenticate(f,directory),/successful original producer/);assert(!f.paths.some(p=>p.endsWith('/zip')));});
 await withRoot(async(f,directory)=>{await assert.rejects(authenticate(f,directory),/success/);},{changeProof:p=>p.status='failed'});
 await withRoot(async(f,directory)=>{f.plan.phases['backend-image'].state='pending';await assert.rejects(authenticate(f,directory),/Pending phase/);assert.equal(f.paths.length,0);});
 await withRoot(async(f,directory)=>{const root=await authenticate(f,directory),changed=copy(f.plan);changed.base=B.replace(/^b/,'e');changed.candidateInputsSHA256=candidateInputsDigest(changed);await assert.rejects(verifyQualificationMetadata({plan:changed,root,token:'synthetic-read-token',fetcher:async()=>{throw Error('Source drift must fail before network');}}));});
});


test('metadata producer timestamps honor only their recorded precision for start and end bounds',async()=>{
 for(const precision of [0,1,2,3])await withRoot(async(f,directory)=>{
  const job=f.jobs.get('2001'),artifact=f.artifacts.get('3001'),quantum=10**(3-precision);
  const format=milliseconds=>new Date(milliseconds).toISOString().replace(/\.([0-9]{3})Z$/,(_,fraction)=>precision?'.'+fraction.slice(0,precision)+'Z':'Z');
  const start=Math.floor(Date.parse(job.started_at)/quantum)*quantum,end=Math.floor(Date.parse(job.completed_at)/quantum)*quantum;
  job.started_at=format(start);job.completed_at=format(end);f.packageRoot(r=>r.phases[0].official.completedAt=job.completed_at);
  const root=await authenticate(f,directory),zipCount=f.paths.filter(p=>p.endsWith('/zip')).length;
  artifact.created_at=new Date(start-1).toISOString();await assert.rejects(verifyQualificationMetadata({plan:f.plan,root,token:'synthetic-read-token',fetcher:f.fetcher}),/outside original producer job/);
  artifact.created_at=new Date(start).toISOString();await verifyQualificationMetadata({plan:f.plan,root,token:'synthetic-read-token',fetcher:f.fetcher});
  artifact.created_at=new Date(end+quantum-1).toISOString();await verifyQualificationMetadata({plan:f.plan,root,token:'synthetic-read-token',fetcher:f.fetcher});
  artifact.created_at=new Date(end+quantum).toISOString();await assert.rejects(verifyQualificationMetadata({plan:f.plan,root,token:'synthetic-read-token',fetcher:f.fetcher}),/outside original producer job/);
  assert.equal(f.paths.filter(p=>p.endsWith('/zip')).length,zipCount,'Timestamp rejection cannot download an original phase or Q ZIP again');
 });
});

test('branded metadata observation rechecks fixed Q validity before phase metadata without another ZIP',async()=>withRoot(async(f,directory)=>{
 const root=await authenticate(f,directory),originalJob=copy(f.jobs.get('4001')),originalArtifact=copy(f.artifacts.get('5001')),before=f.paths.length;
 await verifyQualificationMetadata({plan:f.plan,root,token:'synthetic-read-token',fetcher:f.fetcher});
 assert.deepEqual(f.paths.slice(before,before+3),['actions/runs/1001/attempts/2','actions/jobs/4001','actions/artifacts/5001'],'Every metadata observation must first read the original fixed Q identities');
 for(const change of [
  ()=>f.jobs.get('4001').conclusion='failure',
  ()=>f.jobs.get('4001').completed_at=new Date(Date.parse(originalJob.completed_at)+1).toISOString(),
  ()=>f.artifacts.get('5001').expired=true,
  ()=>f.artifacts.get('5001').expires_at='2000-01-01T00:00:00Z',
  ()=>f.artifacts.get('5001').digest='sha256:'+'0'.repeat(64),
  ()=>f.artifacts.delete('5001'),
 ]){
  f.jobs.set('4001',copy(originalJob));f.artifacts.set('5001',copy(originalArtifact));change();const boundary=f.paths.length;
  await assert.rejects(verifyQualificationMetadata({plan:f.plan,root,token:'synthetic-read-token',fetcher:f.fetcher}));
  assert(f.paths.slice(boundary).every(p=>['actions/runs/1001/attempts/2','actions/jobs/4001','actions/artifacts/5001'].includes(p)),'Invalid Q must stop before any phase request');
 }
 f.jobs.set('4001',copy(originalJob));f.artifacts.set('5001',copy(originalArtifact));const denied=[];
 await assert.rejects(verifyQualificationMetadata({plan:f.plan,root,token:'synthetic-read-token',fetcher:async(url,options)=>{const path=new URL(url).pathname.replace('/repos/'+REPOSITORY+'/','');denied.push(path);if(path==='actions/artifacts/5001')return {status:403};return f.fetcher(url,options);}}),/no retry\/fallback/);
 assert.equal(denied.filter(p=>p==='actions/artifacts/5001').length,1);assert(denied.every(p=>['actions/runs/1001/attempts/2','actions/jobs/4001','actions/artifacts/5001'].includes(p)));
 assert.equal(f.paths.filter(p=>p.endsWith('/zip')).length,1,'An already branded root never triggers another ZIP download during metadata checks');
}));
